#
# 01-Install-ADDSForest.ps1
# Creates the lab.internal AD forest on DC01 (Windows Server 2025, 10.10.10.10).
# Generated by the AD DS Configuration Wizard ("View script") during the lab build.
# Prerequisite: AD-Domain-Services role installed. Run as Administrator on DC01.
# Prompts for the DSRM (Safe Mode) password at runtime; no secrets are stored here.
#

Import-Module ADDSDeployment
Install-ADDSForest `
-CreateDnsDelegation:$false `
-DatabasePath "C:\WINDOWS\NTDS" `
-DomainMode "Win2025" `
-DomainName "lab.internal" `
-DomainNetbiosName "LAB" `
-ForestMode "Win2025" `
-InstallDns:$true `
-LogPath "C:\WINDOWS\NTDS" `
-NoRebootOnCompletion:$false `
-SysvolPath "C:\WINDOWS\SYSVOL" `
-Force:$true
